{
  "conversations": [
    {
      "title": "Describe my symptoms",
      "lines": [
        { "speaker": "you", "text": "My stomach hurts." },
        { "speaker": "partner", "text": "Where does it hurt?" },
        { "speaker": "you", "text": "Right here." },
        { "speaker": "partner", "text": "How long has it hurt?" },
        { "speaker": "you", "text": "Since yesterday." },
        { "speaker": "you", "text": "Since this morning.", "or": true }
      ],
      "vocab": [
        "stomach",
        "hurt",
        "yesterday",
        "morning",
        "pain"
      ]
    },
    {
      "title": "Ask about medication",
      "lines": [
        { "speaker": "you", "text": "What do you have for stomach ache?" },
        { "speaker": "partner", "text": "Take these pills." },
        { "speaker": "you", "text": "How many should I take?" },
        { "speaker": "partner", "text": "Take two pills after meals." },
        { "speaker": "you", "text": "Is it strong?" },
        { "speaker": "partner", "text": "It's moderate." }
      ],
      "vocab": [
        "pill",
        "meal",
        "strong",
        "take",
        "dose"
      ]
    },
    {
      "title": "Explain allergies",
      "lines": [
        { "speaker": "you", "text": "Are there any side effects?" },
        { "speaker": "partner", "text": "Do you have any allergies?" },
        { "speaker": "you", "text": "I'm allergic to penicillin." },
        { "speaker": "you", "text": "I don't have any allergies.", "or": true },
        { "speaker": "partner", "text": "This medicine is safe for you." },
        { "speaker": "you", "text": "Thank you." }
      ],
      "vocab": [
        "allergic",
        "allergy",
        "safe",
        "effect",
        "medicine"
      ]
    }
  ]
}
